//! Hardware initialisation sequences and default processing coefficients.
//!
//! The hardware init is a small, fixed sequence that resets the chip and
//! puts it into Hi-Z mode, ready for I2S clocks. This cannot be generated
//! dynamically — it is required for every TAS5830 power-on.
//!
//! The processing coefficients (crossover, DRC, routing) were originally
//! generated by TI PurePath Console 3 (PPC3). They are stored here as
//! a flat `(register, value)` sequence that includes book/page switches.
//! Eventually these should be loaded from a config file on flash.

/// Phase 1: Reset + enter Hi-Z. Run BEFORE I2S clocks start.
///
/// After this sequence the device is in Hi-Z mode, waiting for BCLK/WCLK.
#[rustfmt::skip]
pub const HARDWARE_INIT: &[(u8, u8)] = &[
    (0x00, 0x00), // Page 0
    (0x7f, 0x00), // Book 0
    (0x03, 0x02), // Hi-Z mode
    (0x01, 0x11), // Reset
    (0x00, 0x00), // NOPs / settling
    (0x00, 0x00),
    (0x00, 0x00),
    (0x00, 0x00),
    (0x00, 0x00),
    (0x7f, 0x00), // Book 0
    (0x03, 0x02), // Hi-Z mode
];

/// Chip-level register configuration (non-DSP).
///
/// Applied after Hi-Z, before DSP coefficient programming.
/// Sets modulation mode, switching frequency, auto-mute, analog gain, etc.
#[rustfmt::skip]
pub const CHIP_CONFIG: &[(u8, u8)] = &[
    // Deep sleep for DSP programming
    (0x00, 0x00), (0x7f, 0x00), (0x03, 0x00),
    // Chip-specific configuration
    (0x00, 0x00), (0x7f, 0x00), (0x46, 0x01),
    // Back to Hi-Z
    (0x00, 0x00), (0x7f, 0x00), (0x03, 0x02),
    // Clear faults
    (0x00, 0x00), (0x7f, 0x00), (0x78, 0x80),
    // TAS5830-specific registers
    (0x00, 0x00), (0x7f, 0x00),
    (0x61, 0x0b),
    (0x60, 0x01),
    (0x7d, 0x11),
    (0x7e, 0xff),
    // Page 1: auto-mute timing
    (0x00, 0x01),
    (0x51, 0x05),
    // Page 0: modulation + analog
    (0x00, 0x00),
    (0x02, 0x00), // BD modulation, 768 kHz switching
    (0x53, 0x00), // Analog control
    (0x54, 0x00), // Analog gain 0 dB
    // NOPs for settling
    (0x00, 0x00), (0x00, 0x00), (0x00, 0x00), (0x00, 0x00),
    // Enable DSP / biquad processing
    (0x00, 0x00), (0x7f, 0x00), (0x66, 0x87),
];

